cards=[]
c=compact('zhang_shilai','张拾来','张拾来是金沙江边被张堂主拾到的弃婴，长着娃娃脸，从小被训练成替帮会争夺黄金的刀手。他的碎雪刀法精准疾快，能在混战中计算位置、利用敌人动作，可极强的杀人本领并没有给他安全感：他习惯站在最后、背靠墙壁，惧怕背后有人，只有厨子常福让他相信不会害自己。银花儿使他获得短暂亲近，他却也曾因羞耻和敏感挥刀威胁她，不能把这段感情只写成温柔救赎。养育者命他杀旧龙头，又准备借枪声灭口，张拾来临机转身避过要害，负伤投江，被时空旅者救助后藏在常福处。银花儿被折磨时，他知道出面必死而没有救她，终身背负失去与自责；她死后，他仍静养练刀，最终利用散落黄金诱使护卫分心，杀死张堂主，感到复仇并没有预想的满足。后来他改名整容，进入完全不同的显赫生活，原文刻意不揭身份，不能擅自配成真实历史人物。终局保留伤后不如从前的刀术、对人性贪欲的理解与埋藏旧事的愿望，不恢复少年巅峰，也不把旅者技术当作自身能力。','《黄金故事》报仇后改名整容，后半生身份被有意隐去；综合卡采用伤后可行动的成熟阶段，未凭缺失资料叠加新能力','主角','脱离被当作杀人工具的生活并维护有限的私人联系','寡言、警觉，背靠可靠物体，触及旧事时容易沉默','危险贴身时以位置和人心求生；亲密关系触及羞耻时会失控，需要承担后果','不作无效赴死不等于没有愧疚，复仇也不能消除已经发生的伤害',[ab('碎雪刀法','以精准快刀、步位和时机处理近身多人，能切小目标并利用枪手动作','伤后明确大不如前；快刀不能当防弹，曾中枪重伤'),ab('心理诱导与隐匿','让仇敌知道自己未死、长期隐藏，最终以黄金分散护卫注意','并非控制思想，依赖对手的贪欲和现实机会；长期隐藏也造成无力救人的后果')],[ev('071',1431,1439,'弃婴、刀法与失踪'),ev('071',2061,2099,'感情、威胁与羞耻'),ev('071',2325,2357,'中枪和逃脱'),ev('071',2995,3038,'恐惧、常福与隐匿'),ev('071',3091,3205,'银花死亡、复仇和终局身份')],profile='martial')
rate(c,[3,0,1,3,2,8],tier='并',reason='伤后仍有卓越刀术和战术，但体力与刀法明确不如青年；不以比喻闪电推超音速或防弹。')
cards.append(c)
cards.append(compact('chang_fu','常福','常福原是金沙江哥老会龙头的专用厨子，靠出色烹饪赢得白老大尊重，也成为张拾来少有愿意说话的朋友。他生活在夺金、争权和刀手杀人的环境里，熟知行规，却不是只会旁观讲故事的人：张拾来受枪伤后藏在他那里，长期依靠他的照应，传给仇人的消息也由他代办。他看到张拾来无法救银花儿时打墙流血，也目睹银花儿最后去见张龙头的惨状，成为录像之外补全人物结局的关键见证。多年后离开矿区，在上海经营餐馆，又在英国落脚，儿子已近六十仍陪他来见白老大；他自己瘦小而矍铄，健谈，兴致来时也惦记桌上的好菜。他讲述时会用天命解释恶人和受害者，也会为张拾来报仇而眉飞色舞，保留旧江湖的局限，不能把他的每句感慨当作客观结论。终局卡以老年厨师和见证者为主，承认记忆不完整、听不懂时空技术，而不赋予刀手功夫。新的故事中，他能通过饭食和耐心给受伤的人一个藏身之处，是否承受牵连仍应是有代价的选择。','《黄金故事》老年居英国，受邀补述往事，身体矍铄但未展示战斗能力','主角','照应信任自己的人，并把亲见的人间遭遇说清楚','健谈、亲切，熟悉川菜和帮会生活，讲故事会随着情绪改变语气','友人受害时愿秘密庇护，对施害者仍抱强烈恨意','亲见与转述要分清，不懂新技术就承认不懂，照护也可能带来风险',[ab('烹饪与日常庇护','以厨师身份提供饭食、隐蔽和长期照料，后来经营餐馆','没有医疗奇术和完美安全屋，所在环境与他人保密都重要'),ab('地方往事见证','结合录像解释刀手生活、张拾来隐匿与终局','年老记忆会遗忘，不懂复杂技术；感慨和推测不等于事实')],[ev('071',2882,2888,'厨艺与白老大关系'),ev('071',2995,3038,'现时状态、庇护及见证'),ev('071',3091,3151,'补述死亡与复仇'),ev('071',3277,3307,'技术理解有限')],profile='ordinary'))
cards.append(compact('yin_huaer','银花儿','银花儿生活在金沙江淘金帮会控制的环境中，被迫以身体侍奉男人，真实来历很少向人提起。她美丽、善笑，却会在笑里带泪，长期遭受粗暴对待后对男性触碰有强烈厌恶。她并非毫无伤害他人的行为，曾为黄金杀死邀她逃亡的青年；在那个暴力秩序中，她对出路的判断也受恐惧和利益扭曲。张拾来选择了她，两人的缺憾和脆弱使关系变得特殊；他挥刀而没有伤她的举动被她理解为难得的克制，但卡片不能据此把持刀恐吓普遍解释成爱情。张拾来被陷害后，她又被张龙头当作逼他现身的饵，长期遭折磨，容貌和身体衰败。一年多后，她谎称知道藏身地，试图单独接近施害者，计划被识破，最后以匕首自尽，临死仍念着张拾来。终局没有获救逃亡的大团圆，参战须明确恢复最后仍可自主行动的伤弱状态并保留记忆，不把美貌改成魅惑或给她全套武术。演绎可让她在新的安全关系中表达欲望和界线，也保留她曾伤人、曾求生的复杂性。','《黄金故事》长期遭虐后自尽；参战恢复最后可行动的伤弱成人形态并保留终局记忆','主角','摆脱被买卖和支配的生活，珍惜少有的尊重与亲近','会以笑容应付环境，真实情绪常藏在沉默和泪水中','被逼至无路可走时会设计接近施害者，但不具压倒性武力','生存选择可能伤害别人，感情不能自动消除身体界线和既有创伤',[ab('察言观色与隐瞒意图','在受控制环境中应对他人，曾以情报为借口接近张龙头','对方可以识破，不是魅惑、心控或必胜欺骗'),ab('近身用刃','有具体用刀杀人和携匕首的行动','缺乏系统武术展示，终局身体伤弱，不能凭一次行为赋予刀术宗师水平')],[ev('071',2061,2099,'关系与身体界线'),ev('071',2631,2640,'杀逃亡青年及未被记载的处境'),ev('071',3028,3038,'往事和受虐'),ev('071',3091,3103,'终局失败与死亡')],profile='ordinary'))
cards[-1]['adaptations'].append({'change':'恢复最后可自主行动的伤弱身体并保留终局记忆','reason':'原作没有被救出的大团圆；后日谈仍给她重新选择的机会。','power_impact':'不返全盛美貌，不增添超自然魅惑。'})
cards.append(compact('zhang_tangzhu','张堂主','张堂主原掌哥老会子字堂，地位仅次于金沙江龙头，也是将弃婴张拾来养大的那个人。他会反复提起当年救命之恩，把近似父子的关系变成命令和压力，要求张拾来刺杀旧龙头，谎称奉有总坛密令，并以升任堂主诱使合作。其计划不仅要夺权，也要杀掉知情的执行者：利用刺杀现场的枪声掩盖自己开枪，再公开指责张拾来犯上，使保镳成为顺从的新证人。计划因张拾来临机改变位置而留下活口，他一度惊慌忘了补枪，随后又用空枪和保镳互不信任的心理控制局势。成为龙头后，他折磨银花儿引人出面，同时被仇敌可能随时回来的恐惧折磨，睡进铁箱仍无法安宁。最后他带金离开，护卫被金块诱惑分神，全部遭张拾来杀死；他临死还想用养育恩情唤起对方迟疑，没有成功。卡片保留具体的政治计算和对人性弱点的利用，不能因阴谋曾成功便写成全知策士，也不能以养育之恩减轻灭口与虐待的责任。参战恢复最后可行动形态，黄金和帮众都按现场实际资源取得。','《黄金故事》退位带金回总坛途中被张拾来杀死；参战恢复最后可行动形态并保留终局记忆','反派','夺取并保住权力，清除能证明自身阴谋的人','阴沉审慎，常将恩情、规矩和利益一起用来施压','计划出错会短暂失措，随后转而操控目击者与人质','把他人关系视为筹码，却低估长期恐惧和他人不愿继续被控制的决心',[ab('密谋与证人控制','安排借刀杀人、声响掩护和嫁祸，利用保镳彼此不信任','临机变化会打乱计划，无法保证同谋和证人永远服从'),ab('常规枪械','使用盒子炮射击及连射，企图在近距离灭口','有限弹药，曾打空；枪法和时机并非必然击中要害')],[ev('071',1891,2037,'恩情、伪密令和计划'),ev('071',2325,2397,'失败、补枪及操控保镳'),ev('071',3091,3118,'虐待与恐惧'),ev('071',3144,3164,'被杀及最后诉诸恩情')],profile='investigator',aliases=['子字堂张堂主','张龙头']))
cards[-1]['adaptations'].append({'change':'恢复最后可行动形态并保留终局记忆','reason':'原作已遇害，后日谈仅恢复行动接口。','power_impact':'不自动恢复职位、黄金、帮众和绑架对象。'})
cards.append(compact('old_jinsha_leader','金沙江旧龙头','这位未具姓名的哥老会旧龙头由总坛派往金沙江，控制淘金地区与刀手体系，身边有六名一流护卫，腰间携枪，权力建立在江段争夺和帮会层级之上。张堂主是其下最有地位的堂主，表面遵守规矩，实际已准备用张拾来刺杀他。所谓旧龙头私吞黄金、脱离总坛，只来自张堂主为阴谋编造的密令说法，不能照单全收为其已经证实的罪行。真正能确认的是，他所主持的体制让大量劳工困于淘金，刀手通过残酷决斗争取产区，个人安全也离不开护卫和随身枪械。去勘看新夺江段时，他遭张拾来从背后突袭，试图拔枪还击，右臂被斩后仍因既定动作扣发子弹，却未能阻止紧接而来的致命刀击。其死被对外掩饰为暴亡，权位被张堂主接收，他本人没有留下反转或悔悟的后续。卡片以这位制度掌权者及刺杀目标的有限可核面貌呈现，不能凭职位补出无数私人暴行，也不能因成为阴谋受害者抹去其掌握暴力秩序的身份。','《黄金故事》遭张拾来刺杀；参战恢复最后可行动形态并保留终局记忆','阶段性对立者','维持所辖淘金帮会的权力、收益与秩序','以位阶和护卫维持威势，出行有安全安排','遭刺杀时立即拔枪，仍受突袭时机与近身距离限制','权力依赖实际组织和忠诚，规矩不能防止亲近者谋反',[ab('帮会统领','主持淘金地盘和刀手组织，受总坛层级支持','群体行动依赖人手，不能折成个人超能'),ab('随身枪械与近身反应','遇袭拔枪并扣发，具一定实战警觉','被突袭断臂杀死；未证明高于张拾来的刀术或防弹能力')],[ev('071',952,963,'淘金制度与刀手'),ev('071',1993,2009,'伪密令及护卫情形'),ev('071',2156,2162,'随身枪械和护卫'),ev('071',2258,2308,'反应及死亡')],profile='investigator'))
cards[-1]['adaptations'].append({'change':'恢复最后可行动形态并保留终局记忆','reason':'原作已死亡，参战与历史事实分开。','power_impact':'不恢复整支帮会及必然忠诚的护卫。'})
c=compact('duantui_daoshou','断腿刀手','这位来自外帮的刀手曾在神牙台决斗中与张拾来交锋，双腿被快刀斩断，成为罕见的活口。他倒在血泊里求救无人回应，一度准备自行结束痛苦，却被突然现身的一男一女包扎止血。面对陌生人的善意，他没有马上变得信任，而是因为对方的衣着、摄影器材和来历太异常，想以自己拥有的黄金引他们靠近，再用刀加害。两人退到石台边突然消失，他才认作怪神仙，惊惧之下放弃恶念；药物缓解疼痛后，他将自己的断腿埋起，最终舍弃相伴多年的刀。此后他流落乞食，反复向旁人讲述决斗与获救的故事，有时磕头自责，有时也为自己的动机辩护，讲述未必没有选择性。白老大多年后凭录像确认其中关键细节，而其获救来自王居风与高彩虹，不是他自己获得法力。终局卡保留截肢后的身体和失去旧职业的处境，不能自动补上义肢或恢复青年双腿。他既是残酷竞争的执行者又是被丢弃的人，新场景中能否信任别人、是否仍把黄金当作万能诱饵，比重演决斗更值得展开。','《黄金故事》历史回忆中截去双腿后存活乞食，后续生死不详；按截肢后可行动形态部署',['主角','阶段性对立者'],'在失去刀手生计后活下去，并使自己的经历有人相信','反复讲述旧事，既有悔恨也有为自己辩解的习惯','遇到不明帮助时会怀疑甚至想先害人，发现误判后强烈后悔','过去的刀术和财富不能恢复身体，善意也不该因陌生就被视为陷阱',[ab('残存刀手经验','熟悉刀手决斗和帮会规则，保留观察近身风险的经验','双腿已失、弃刀后以生存为主，不能继续按完整身体快攻'),ab('见证与陈述','复述神牙台决斗及现代旅者救治，给后人提供关键证据','会遗漏对自己不利部分，不懂摄影与时空技术')],[ev('071',2657,2692,'原身份、截肢与获救'),ev('071',2720,2749,'意图加害、后悔、弃刀及乞食')],profile='ordinary')
rate(c,[1,0,1,1,1,4],neg=(3,1,1),tier='纸',reason='截肢后保留经验但失去原有机动和职业状态，不采用受伤前刀手战力。')
c['baseline'].update({'speed':'双腿被截，移动受显著限制；未确证拥有义肢或专门载具。','durability':'止血后生还但无肢体再生；仍受常见伤害与照护条件限制。'})
cards.append(c)
save(cards)
